namespace Account.Declaration
{
    public partial class frmReceiptPlan_V2 : FormBase, IForm
    {
        #region Consts

        public const string PERMISSION_ADD = "ACC_ReceiptPlan_Add";
        public const string PERMISSION_DELETE = "ACC_ReceiptPlan_Delete";
        public const string PERMISSION_EDIT = "ACC_ReceiptPlan_Edit";
        public const string PERMISSION_VIEW = "ACC_ReceiptPlan_View";

        private const string COL_SPECIALBRANCHID = "SpecialBranchID";
        private const string COL_SPECIALBRANCHNAME = "SpecialBranchName";
        private const string COL_LEARNINGLEVEL = "LearningLevel";
        private const string COL_TRAININGLEVELID = "TrainingLevelID";
        private const string COL_TRAININGLEVELNAME = "TrainingLevelName";
        private const string COL_BRANCHNAME = "BranchName";
        private const string COL_QUANTITY = "Quantity";
        private const string COL_PRICE = "Price";
        private const string COL_MONEY = "Money";
        private const string COL_RECEIPTPLANID = "ReceiptPlanID";
        private const string COL_RECEIPTSEGMENTID = "ReceiptSegmentID";
        private const string COL_ISMODIFIED = "IsModified";

        #endregion

        #region Variables

        bool bolIsEditing = false;
        private DataTable dtbData;
        private DataTable dtbOriginalData;
        private bool bolIsLoading = false;

        #endregion

        #region IForm Members

        private static frmReceiptPlan_V2 _instance = null;

        public static frmReceiptPlan_V2 Instance
        {
            get
            {
                if (_instance == null)
                    _instance = new frmReceiptPlan_V2();
                return _instance;
            }
        }

        public void Run(bool isShowDialog)
        {
            FormManager.Run(Instance, isShowDialog);
        }

        #endregion

        public frmReceiptPlan_V2()
        {
            InitializeComponent();
        }

        public void LoadReferenceData()
        {
            if (InvokeRequired)
                Invoke(new MethodInvoker(LoadReferenceData));
            else
            {
                uCourseTypeLevel.InitData();
                uSpecialBranch.InitData();
                uYearSemester.InitData();
                AccountService.ACC_ReceiptSegmentService.InitLookUpEdit(lookupReceiptSegmentID);
            }
        }

        public void RefreshReferenceData()
        {
            uCourseTypeLevel.RefrehData();
            uSpecialBranch.RefrehData();
            uYearSemester.RefrehData();
            AccountService.ACC_ReceiptSegmentService.HaveNewData = true;
            AccountService.ACC_ReceiptSegmentService.InitLookUpEdit(lookupReceiptSegmentID);
        }

        private void CreateGridColumns()
        {
            gvData.Columns.Clear();

            // Cot SpecialBranchID (an)
            DevExpress.XtraGrid.Columns.GridColumn colSpecialBranchID = gvData.Columns.AddField(COL_SPECIALBRANCHID);
            colSpecialBranchID.Caption = "SpecialBranchID";
            colSpecialBranchID.Visible = false;
            colSpecialBranchID.OptionsColumn.ReadOnly = true;

            // Cot Ten nghe
            DevExpress.XtraGrid.Columns.GridColumn colSpecialBranchName = gvData.Columns.AddField(COL_SPECIALBRANCHNAME);
            colSpecialBranchName.Caption = "Tên nghề";
            colSpecialBranchName.VisibleIndex = 0;
            colSpecialBranchName.OptionsColumn.ReadOnly = true;
            colSpecialBranchName.Width = 150;

            // Cot LearningLevel (an)
            DevExpress.XtraGrid.Columns.GridColumn colLearningLevel = gvData.Columns.AddField(COL_LEARNINGLEVEL);
            colLearningLevel.Caption = "LearningLevel";
            colLearningLevel.Visible = false;
            colLearningLevel.OptionsColumn.ReadOnly = true;

            // Cot TrainingLevelID
            DevExpress.XtraGrid.Columns.GridColumn colTrainingLevelID = gvData.Columns.AddField(COL_TRAININGLEVELID);
            colTrainingLevelID.Caption = "TrainingLevelID";
            colTrainingLevelID.VisibleIndex = 1;
            colTrainingLevelID.OptionsColumn.ReadOnly = true;
            colTrainingLevelID.Width = 80;

            // Cot Ten trinh do dao tao
            DevExpress.XtraGrid.Columns.GridColumn colTrainingLevelName = gvData.Columns.AddField(COL_TRAININGLEVELNAME);
            colTrainingLevelName.Caption = "Trình độ đào tạo";
            colTrainingLevelName.VisibleIndex = 2;
            colTrainingLevelName.OptionsColumn.ReadOnly = true;
            colTrainingLevelName.Width = 180;

            // Cot BranchName
            DevExpress.XtraGrid.Columns.GridColumn colBranchName = gvData.Columns.AddField(COL_BRANCHNAME);
            colBranchName.Caption = "Ngành";
            colBranchName.VisibleIndex = 3;
            colBranchName.OptionsColumn.ReadOnly = true;
            colBranchName.Width = 120;

            // Cot Quantity
            DevExpress.XtraGrid.Columns.GridColumn colQuantity = gvData.Columns.AddField(COL_QUANTITY);
            colQuantity.Caption = "Số tín chỉ";
            colQuantity.VisibleIndex = 4;
            colQuantity.OptionsColumn.ReadOnly = false;
            colQuantity.Width = 100;
            colQuantity.DisplayFormat.FormatType = DevExpress.Utils.FormatType.Numeric;
            colQuantity.DisplayFormat.FormatString = "n0";
            colQuantity.AppearanceCell.BackColor = Color.FromArgb(135, 206, 250); // #87CEFA

            // Cot Price
            DevExpress.XtraGrid.Columns.GridColumn colPrice = gvData.Columns.AddField(COL_PRICE);
            colPrice.Caption = "Đơn giá";
            colPrice.VisibleIndex = 5;
            colPrice.OptionsColumn.ReadOnly = false;
            colPrice.Width = 120;
            colPrice.DisplayFormat.FormatType = DevExpress.Utils.FormatType.Numeric;
            colPrice.DisplayFormat.FormatString = "n0";
            colPrice.AppearanceCell.BackColor = Color.FromArgb(255, 255, 192); // #FFFFC0

            // Cot Money
            DevExpress.XtraGrid.Columns.GridColumn colMoney = gvData.Columns.AddField(COL_MONEY);
            colMoney.Caption = "Tổng tiền";
            colMoney.VisibleIndex = 6;
            colMoney.OptionsColumn.ReadOnly = false;
            colMoney.Width = 150;
            colMoney.DisplayFormat.FormatType = DevExpress.Utils.FormatType.Numeric;
            colMoney.DisplayFormat.FormatString = "n0";
            colMoney.AppearanceCell.BackColor = Color.FromArgb(192, 255, 192); // #C0FFC0

            // Cot ReceiptPlanID (an)
            DevExpress.XtraGrid.Columns.GridColumn colReceiptPlanID = gvData.Columns.AddField(COL_RECEIPTPLANID);
            colReceiptPlanID.Caption = "ReceiptPlanID";
            colReceiptPlanID.Visible = false;
            colReceiptPlanID.OptionsColumn.ReadOnly = true;

            // Cot ReceiptSegmentID (an)
            DevExpress.XtraGrid.Columns.GridColumn colReceiptSegmentID = gvData.Columns.AddField(COL_RECEIPTSEGMENTID);
            colReceiptSegmentID.Caption = "ReceiptSegmentID";
            colReceiptSegmentID.Visible = false;
            colReceiptSegmentID.OptionsColumn.ReadOnly = true;

            // Cot IsModified (an)
            DevExpress.XtraGrid.Columns.GridColumn colIsModified = gvData.Columns.AddField(COL_ISMODIFIED);
            colIsModified.Caption = "IsModified";
            colIsModified.Visible = false;
            colIsModified.OptionsColumn.ReadOnly = true;

            gvData.OptionsBehavior.Editable = true;
            gvData.OptionsSelection.MultiSelect = false;
            gvData.OptionsView.ShowAutoFilterRow = false;
            gvData.OptionsView.ColumnAutoWidth = false;
        }

        public void LoadData()
        {
            if (InvokeRequired)
            {
                Invoke(new MethodInvoker(LoadData));
            }
            else
            {
                bolIsLoading = true;

                try
                {
                    string strCourseID = uCourseTypeLevel.CourseIDEditValue;
                    string strTrainingLevelID = uCourseTypeLevel.TrainingLevelIDEditValue;
                    string strTrainingType = uCourseTypeLevel.TrainingTypeEditValue;
                    string strBranchID = uSpecialBranch.BranchEditValue;
                    string strSpecialBranchID = uSpecialBranch.SpecialBranchEditValue;
                    int? intYearID = uYearSemester.YearIDEditValueInt32;
                    int? intSemester = uYearSemester.SemesterEditValueInt32;

                    ACC_ReceiptPlan obj = new ACC_ReceiptPlan();
                    dtbData = obj.GetDataTable("ACC_ReceiptPlan_LoadGrid_V2",
                                    "@CourseID", strCourseID,
                                    "@TrainingLevelID", strTrainingLevelID,
                                    "@TrainingType", strTrainingType,
                                    "@BranchID", strBranchID,
                                    "@SpecialBranchID", strSpecialBranchID,
                                    "@YearID", intYearID,
                                    "@Semester", intSemester);

                    if (dtbData != null)
                    {
                        // Luu ban sao du lieu goc de so sanh
                        dtbOriginalData = dtbData.Copy();

                        // Tao column IsModified neu chua co
                        if (!dtbData.Columns.Contains(COL_ISMODIFIED))
                            dtbData.Columns.Add(COL_ISMODIFIED, typeof(bool));

                        gcData.DataSource = dtbData;

                        CreateGridColumns();

                        if (gvData.Columns.Count > 0)
                            gvData.BestFitColumns();

                        btnUpdate.Enabled = true;
                    }
                    else
                    {
                        MessageManager.Error("Việc lấy thông tin bị lỗi!");
                    }
                }
                catch (Exception ex)
                {
                    MessageManager.Error("Lỗi khi tải dữ liệu: " + ex.Message);
                }
                finally
                {
                    bolIsLoading = false;
                }
            }
        }

        #region Support Functions

        private void CheckPermission()
        {
            mnuItemAdd.Enabled = UserSession.HasPermission(PERMISSION_ADD);
            btnDelete.Enabled = UserSession.HasPermission(PERMISSION_DELETE);
            btnUpdate.Enabled = UserSession.HasPermission(PERMISSION_EDIT) || UserSession.HasPermission(PERMISSION_ADD);
        }

        #endregion

        #region Form Actions

        private void frmReceiptPlan_Load(object sender, EventArgs e)
        {
            CheckPermission();
            SetToolTip();
            new Thread(LoadReferenceData).Start();

            // Khoi tao grid
            gvData.OptionsBehavior.Editable = true;
            gvData.OptionsSelection.MultiSelect = false;
            gvData.OptionsView.ShowAutoFilterRow = false;
            gvData.ResetGridColumn = false;

            // Gan su kien
            btnUpdate.Click += new EventHandler(btnUpdate_Click);
            gvData.CellValueChanged += new DevExpress.XtraGrid.Views.Base.CellValueChangedEventHandler(gvData_CellValueChanged);
            gvData.RowCellStyle += new DevExpress.XtraGrid.Views.Grid.RowCellStyleEventHandler(gvData_RowCellStyle);
            uCourseTypeLevel.EditValueChanged += new DeclarationManager.Education.UCourseTypeLevel.EditValueChangedDelegate(uCourseTypeLevel_EditValueChanged);
        }

        #endregion

        private void btnSearch_Click(object sender, EventArgs e)
        {
            string strCourseID = uCourseTypeLevel.CourseIDEditValue;

            if (String.IsNullOrEmpty(strCourseID))
            {
                MessageManager.Warning("Vui lòng chọn Khóa trước khi tìm kiếm.");
                return;
            }

            new Thread(LoadData).Start();
        }

        private void uCourseTypeLevel_EditValueChanged(object sender, EventArgs arg)
        {
            if (uCourseTypeLevel.TrainingLevel != null)
                uSpecialBranch.SpecialBranchFilter = "LearningLevel = " + uCourseTypeLevel.TrainingLevel.LearningLevel;
            else
                uSpecialBranch.SpecialBranchFilter = "";
        }

        private void gvData_CellValueChanged(object sender, DevExpress.XtraGrid.Views.Base.CellValueChangedEventArgs e)
        {
            if (bolIsLoading)
                return;

            DataRow drw = gvData.GetFocusedDataRow();
            if (drw == null)
                return;

            // Danh dau dong da sua
            drw[COL_ISMODIFIED] = true;

            // Tu dong tinh Money = Quantity * Price
            if (e.Column.FieldName == COL_QUANTITY || e.Column.FieldName == COL_PRICE)
            {
                object objQuantity = drw[COL_QUANTITY];
                object objPrice = drw[COL_PRICE];

                if (objQuantity != null && objPrice != null && objQuantity != DBNull.Value && objPrice != DBNull.Value)
                {
                    try
                    {
                        decimal decQuantity = Convert.ToDecimal(objQuantity);
                        decimal decPrice = Convert.ToDecimal(objPrice);

                        if (decQuantity > 0 && decPrice > 0)
                        {
                            drw[COL_MONEY] = decQuantity * decPrice;
                        }
                    }
                    catch
                    {
                        // Khong tu tinh duoc
                    }
                }
            }
        }

        private void gvData_RowCellStyle(object sender, DevExpress.XtraGrid.Views.Grid.RowCellStyleEventArgs e)
        {
            DataRow drw = gvData.GetDataRow(e.RowHandle);
            if (drw != null)
            {
                object objIsModified = drw[COL_ISMODIFIED];
                if (objIsModified != null && objIsModified != DBNull.Value && Convert.ToBoolean(objIsModified))
                {
                    e.Appearance.BackColor = Color.LightPink;
                    e.Appearance.BackColor2 = Color.LightPink;
                }
            }
        }

        private void btnUpdate_Click(object sender, EventArgs e)
        {
            if (!IsValidSaveConditions())
                return;

            string strCourseID = uCourseTypeLevel.CourseIDEditValue;
            string strTrainingLevelID = uCourseTypeLevel.TrainingLevelIDEditValue;
            string strTrainingType = uCourseTypeLevel.TrainingTypeEditValue;
            string strSpecialBranchID = uSpecialBranch.SpecialBranchEditValue;
            string strBranchID = uSpecialBranch.BranchEditValue;
            string strReceiptSegmentID = lookupReceiptSegmentID.EditValueString;
            int? intYearID = uYearSemester.YearIDEditValueInt32;
            int? intSemester = uYearSemester.SemesterEditValueInt32;

            List<string> listError = new List<string>();
            int intSuccessCount = 0;
            int intFailCount = 0;

            if (dtbData == null)
            {
                MessageManager.Warning("Không có dữ liệu để cập nhật.");
                return;
            }

            for (int i = 0; i < dtbData.Rows.Count; i++)
            {
                DataRow drw = dtbData.Rows[i];

                // Chi luu dong da sua hoac dong co du lieu
                object objIsModified = drw[COL_ISMODIFIED];
                bool bolIsModified = (objIsModified != null && objIsModified != DBNull.Value && Convert.ToBoolean(objIsModified));

                object objMoney = drw[COL_MONEY];
                bool bolHasMoney = (objMoney != null && objMoney != DBNull.Value);

                // Neu khong sua va khong co tien thi bo qua
                if (!bolIsModified && !bolHasMoney)
                    continue;

                // Kiem tra Money hop le
                if (!bolHasMoney)
                {
                    listError.Add(String.Format("Dòng {0}: Chưa có tổng tiền.", i + 1));
                    intFailCount++;
                    continue;
                }

                decimal decMoney = Convert.ToDecimal(objMoney);
                if (decMoney <= 0)
                {
                    listError.Add(String.Format("Dòng {0}: Tổng tiền không hợp lệ.", i + 1));
                    intFailCount++;
                    continue;
                }

                // Lay thong tin tu dong
                string strRowSpecialBranchID = Convert.ToString(drw[COL_SPECIALBRANCHID]);
                string strRowTrainingLevelID = Convert.ToString(drw[COL_TRAININGLEVELID]);

                object objQuantity = drw[COL_QUANTITY];
                object objPrice = drw[COL_PRICE];
                int? intQuantity = null;
                decimal? decPrice = null;

                if (objQuantity != null && objQuantity != DBNull.Value)
                    intQuantity = Convert.ToInt32(objQuantity);

                if (objPrice != null && objPrice != DBNull.Value)
                    decPrice = Convert.ToDecimal(objPrice);

                // Kiem tra ReceiptPlanID da co hay chua
                object objReceiptPlanID = drw[COL_RECEIPTPLANID];
                bool bolIsNew = (objReceiptPlanID == null || objReceiptPlanID == DBNull.Value || Convert.ToInt32(objReceiptPlanID) == 0);

                ACC_ReceiptPlan itemSave = new ACC_ReceiptPlan();
                itemSave.CourseID = strCourseID;
                itemSave.TrainingLevelID = strRowTrainingLevelID;
                itemSave.TrainingType = strTrainingType;
                itemSave.SpecialBranchID = strRowSpecialBranchID;
                itemSave.ReceiptSegmentID = strReceiptSegmentID;
                itemSave.Money = decMoney;
                itemSave.Quantity = intQuantity;
                itemSave.Price = decPrice;
                itemSave.YearID = intYearID;
                itemSave.Semester = intSemester;
                itemSave.Description = "";
                itemSave.BeginDate = null;
                itemSave.EndDate = null;

                if (bolIsNew)
                {
                    itemSave.CreatedUser = UserSession.Username;
                    if (!itemSave.Add())
                    {
                        listError.Add(String.Format("Dòng {0}: Lỗi khi thêm dữ liệu.", i + 1));
                        intFailCount++;
                    }
                    else
                    {
                        // Cap nhat lai ReceiptPlanID vao dong
                        if (itemSave.ReceiptPlanID != null)
                            drw[COL_RECEIPTPLANID] = itemSave.ReceiptPlanID;
                        drw[COL_ISMODIFIED] = false;
                        intSuccessCount++;
                    }
                }
                else
                {
                    itemSave.ReceiptPlanID = Convert.ToInt32(objReceiptPlanID);
                    itemSave.UpdatedUser = UserSession.Username;
                    if (!itemSave.Update())
                    {
                        listError.Add(String.Format("Dòng {0}: Lỗi khi cập nhật dữ liệu.", i + 1));
                        intFailCount++;
                    }
                    else
                    {
                        drw[COL_ISMODIFIED] = false;
                        intSuccessCount++;
                    }
                }
            }

            // Hien thi thong bao ket qua
            string strMessage = "Cập nhật hoàn tất.\n\n";
            strMessage += String.Format("Lưu thành công: {0} dòng.\n", intSuccessCount);
            strMessage += String.Format("Không lưu: {0} dòng.\n", intFailCount);

            if (listError.Count > 0)
            {
                strMessage += "\nChi tiết lỗi:\n";
                for (int j = 0; j < listError.Count; j++)
                {
                    strMessage += "* " + listError[j] + "\n";
                }
            }

            if (intFailCount > 0)
                MessageManager.Warning(strMessage);
            else
                MessageManager.Info(strMessage);

            // Refresh lai du lieu goc
            if (dtbOriginalData != null)
                dtbOriginalData = dtbData.Copy();
        }

        private bool IsValidSaveConditions()
        {
            string strCourseID = uCourseTypeLevel.CourseIDEditValue;
            string strTrainingLevelID = uCourseTypeLevel.TrainingLevelIDEditValue;
            string strTrainingType = uCourseTypeLevel.TrainingTypeEditValue;
            string strSpecialBranchID = uSpecialBranch.SpecialBranchEditValue;
            int? intYearID = uYearSemester.YearIDEditValueInt32;
            int? intSemester = uYearSemester.SemesterEditValueInt32;

            if (String.IsNullOrEmpty(strCourseID) ||
                String.IsNullOrEmpty(strTrainingLevelID) ||
                String.IsNullOrEmpty(strTrainingType) ||
