                return false;
            }

            return true;
        }

        private void btnDelete_Click(object sender, EventArgs e)
        {
            DataRow drw = gvData.GetFocusedDataRow();
            if (drw != null)
            {
                object objReceiptPlanID = drw[COL_RECEIPTPLANID];
                if (objReceiptPlanID == null || objReceiptPlanID == DBNull.Value || Convert.ToInt32(objReceiptPlanID) == 0)
                {
                    MessageManager.Warning("Dòng này chưa có dữ liệu để xóa.");
                    return;
                }

                ACC_ReceiptPlan objReceiptPlan = new ACC_ReceiptPlan();
                objReceiptPlan.ReceiptPlanID = Convert.ToInt32(objReceiptPlanID);
                if (!objReceiptPlan.Get())
                {
                    ErrorManager.Error("Lấy thông tin để xoá bị lỗi!");
                    return;
                }

                string strReceiptSegmentID = Convert.ToString(drw[COL_RECEIPTSEGMENTID]);
                string strCourseID = uCourseTypeLevel.CourseIDEditValue;
                string strRowTrainingLevelID = Convert.ToString(drw[COL_TRAININGLEVELID]);
                string strRowSpecialBranchID = Convert.ToString(drw[COL_SPECIALBRANCHID]);

                string str = objReceiptPlan.ExistStudentReceiptPlan();
                if (str != "")
                {
                    MessageManager.Warning("Kế hoạch thu đã được lên dự kiến thu ở các lớp: \r\n" + str + "Bạn hãy xoá dự kiến thu trước khi xoá kế hoạch thu này!");
                    return;
                }

                if (MessageManager.Confirm("Bạn muốn xoá dữ liệu này!") == System.Windows.Forms.DialogResult.Yes)
                {
                    objReceiptPlan.BeginTransaction();
                    objReceiptPlan.ReceiptPlanID = Convert.ToInt32(objReceiptPlanID);
                    objReceiptPlan.ReceiptSegmentID = strReceiptSegmentID;
                    objReceiptPlan.CourseID = strCourseID;
                    objReceiptPlan.TrainingLevelID = strRowTrainingLevelID;
                    objReceiptPlan.TrainingType = uCourseTypeLevel.TrainingTypeEditValue;
                    objReceiptPlan.BeginTransaction();
                    if (objReceiptPlan.Delete())
                        if (objReceiptPlan.DeleteStudentReceiptPlan())
                        {
                            objReceiptPlan.CommitTransaction();
                            gvData.DeleteRow(gvData.FocusedRowHandle);
                            return;
                        }
                    MessageManager.Error("Xóa thông tin thất bại");
                }
            }
        }

